import { one, q } from "../db";
import { log } from "../audit";
import { emailProvider, SendError } from "./providers";
import { renderEmail, type TemplateData } from "./templates";
import type { JobKind } from "./jobs";

type Job = { id: string; reservation_id: string | null; kind: JobKind; recipient: string; attempts: number; max_attempts: number };

const STALE_LOCK = "5 minutes";

/**
 * Claim and process due notification jobs. Safe to run from several processes at once:
 * FOR UPDATE SKIP LOCKED hands each job to exactly one worker.
 */
export async function processDueJobs(limit = 10): Promise<{ sent: number; failed: number; retried: number; notSent: number; cancelled: number }> {
  const tally = { sent: 0, failed: 0, retried: 0, notSent: 0, cancelled: 0 };
  // A worker that died mid-send leaves a job "sending"; put it back in the queue.
  await q(`UPDATE notification_jobs SET status = 'queued', updated_at = now() WHERE status = 'sending' AND locked_at < now() - interval '${STALE_LOCK}'`);
  const jobs = await q<Job>(
    `UPDATE notification_jobs SET status = 'sending', locked_at = now(), attempts = attempts + 1, updated_at = now()
      WHERE id IN (SELECT id FROM notification_jobs WHERE status = 'queued' AND run_at <= now() ORDER BY run_at LIMIT $1 FOR UPDATE SKIP LOCKED)
      RETURNING id, reservation_id, kind, recipient, attempts, max_attempts`,
    [limit],
  );
  for (const job of jobs) {
    const provider = emailProvider();
    try {
      const data = await one<TemplateData & { status: string; notify_consent: boolean; erased_at: Date | null }>(
        `SELECT b.name AS business_name, b.timezone, b.address, b.phone, p.arrival_instructions, p.cancellation_policy,
                c.name AS customer_name, c.email AS customer_email, c.notify_consent, c.erased_at,
                r.reference, r.party_size, r.starts_at, r.status, s.name AS service_name, t.id AS ticket_id
           FROM reservations r
           JOIN businesses b ON b.id = r.business_id
           JOIN business_policies p ON p.business_id = b.id
           JOIN customers c ON c.id = r.customer_id
           JOIN services s ON s.id = r.service_id
           LEFT JOIN tickets t ON t.reservation_id = r.id
          WHERE r.id = $1`,
        [job.reservation_id],
      );
      // Re-check at send time: the booking may have changed since the job was queued.
      const stale =
        !data || !data.customer_email || !data.notify_consent || data.erased_at ||
        (job.kind === "cancellation" ? data.status !== "cancelled" : !["confirmed", "pending"].includes(data.status)) ||
        (job.kind === "reminder" && data.starts_at.getTime() < Date.now());
      if (stale) {
        await finish(job.id, "cancelled", null);
        tally.cancelled++;
        continue;
      }
      const email = renderEmail(job.kind, data!);
      const res = await provider.send(email);
      if (!provider.delivers) {
        // Be honest: nothing left the server.
        await attempt(job.id, provider.name, false, null, "No email provider configured; message was not sent.");
        await finish(job.id, "not_sent", "No email provider configured.");
        tally.notSent++;
      } else {
        await attempt(job.id, provider.name, true, res.id ?? null, null);
        await finish(job.id, "sent", null);
        tally.sent++;
      }
    } catch (e) {
      const msg = (e as Error).message.slice(0, 500);
      const transient = e instanceof SendError ? e.transient : true;
      await attempt(job.id, provider.name, false, null, msg);
      if (transient && job.attempts < job.max_attempts) {
        // Exponential backoff: 1, 2, 4, 8 minutes...
        await q(
          `UPDATE notification_jobs SET status = 'queued', last_error = $2, locked_at = NULL,
                  run_at = now() + make_interval(mins => $3), updated_at = now() WHERE id = $1`,
          [job.id, msg, 2 ** (job.attempts - 1)],
        );
        tally.retried++;
      } else {
        await finish(job.id, "failed", msg);
        tally.failed++;
        log("warn", "notification failed", { job: job.id, kind: job.kind, attempts: job.attempts });
      }
    }
  }
  return tally;
}

async function attempt(jobId: string, provider: string, ok: boolean, providerId: string | null, error: string | null) {
  await q("INSERT INTO notification_attempts (job_id, provider, ok, provider_id, error) VALUES ($1,$2,$3,$4,$5)", [jobId, provider, ok, providerId, error]);
}
async function finish(jobId: string, status: string, error: string | null) {
  await q("UPDATE notification_jobs SET status = $2, last_error = $3, locked_at = NULL, updated_at = now() WHERE id = $1", [jobId, status, error]);
}

const g = globalThis as unknown as { __abcWorker?: NodeJS.Timeout };

export function startWorker(intervalMs = 5000) {
  if (g.__abcWorker) return;
  let running = false;
  g.__abcWorker = setInterval(async () => {
    if (running) return;
    running = true;
    try { await processDueJobs(); } catch (e) { log("error", "worker tick failed", { error: (e as Error).message }); } finally { running = false; }
  }, intervalMs);
  g.__abcWorker.unref?.();
  log("info", "notification worker started", { intervalMs });
}
