import nodemailer from "nodemailer";
import { env } from "../env";

export type Email = { to: string; subject: string; text: string; html: string };

/** Thrown by providers. `transient` errors are retried with backoff; permanent ones are not. */
export class SendError extends Error {
  constructor(message: string, public transient: boolean) { super(message); }
}

export interface EmailProvider {
  name: string;
  /** false = this provider does not deliver anything (development log). */
  delivers: boolean;
  send(email: Email): Promise<{ id?: string }>;
}

const logProvider: EmailProvider = {
  name: "log",
  delivers: false,
  async send() { return {}; },
};

function smtpProvider(): EmailProvider {
  const transport = nodemailer.createTransport({
    host: process.env.SMTP_HOST,
    port: Number(process.env.SMTP_PORT) || 587,
    secure: process.env.SMTP_SECURE === "true",
    auth: process.env.SMTP_USER ? { user: process.env.SMTP_USER, pass: process.env.SMTP_PASS } : undefined,
    connectionTimeout: 10_000,
    socketTimeout: 15_000,
    tls: process.env.SMTP_TLS_INSECURE === "1" ? { rejectUnauthorized: false } : undefined, // tests only
  });
  return {
    name: "smtp",
    delivers: true,
    async send(email) {
      try {
        const info = await transport.sendMail({ from: env.emailFrom, to: email.to, subject: email.subject, text: email.text, html: email.html });
        if (info.rejected?.length) throw new SendError(`Recipient rejected: ${info.rejected.join(", ")}`, false);
        return { id: info.messageId };
      } catch (e) {
        if (e instanceof SendError) throw e;
        const code = (e as { responseCode?: number }).responseCode;
        // 5xx from the mail server is a definitive "no"; everything else (4xx, timeouts, DNS) may succeed later.
        throw new SendError((e as Error).message, !(code && code >= 500));
      }
    },
  };
}

let override: EmailProvider | null = null;
let cached: EmailProvider | null = null;

export function emailProvider(): EmailProvider {
  if (override) return override;
  if (!cached) cached = env.emailProvider === "smtp" && process.env.SMTP_HOST ? smtpProvider() : logProvider;
  return cached;
}

/** Tests replace the provider to simulate failures. */
export function setEmailProviderForTests(p: EmailProvider | null) { override = p; cached = null; }
